    /*
     * Add to the Appointments
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	MROFacility
     */
    public MROFacility addToAppointments( UUID parentId, MaintenanceAppointment addTo ) {
	    LOGGER.info("handling AssignAppointmentsToMROFacilityEvent - " );
	    
	    MROFacility parentEntity = repository.findById(parentId).get();
	    MaintenanceAppointment child = registry.project( MaintenanceAppointment.class, addTo.getMaintenanceAppointmentId());
	    
	    parentEntity.getAppointments().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

